public static int countMammals(Animal[] zoo) {
    int count = 0;
    for (int i = 0; i < zoo.length; i++) {
        if (zoo[i] instanceof Mammal) {
            count++;
        }
    }
    return count;
}

public static double totalMilk(Animal[] zoo) {
    double sum = 0;
    for (int i = 0; i < zoo.length; i++) {
        if (zoo[i] instanceof Mammal) {
            Mammal m = (Mammal) zoo[i];
            sum += m.getMilk();
        }
    }
    return sum;
}

